165	            claims.update(claim);
166	            log.record(claim, user);
167	            opened++;
168	            Person person = everyone.stream().filter((p) -> p.getId() == claim.getPersonId())
169	                    .findFirst().orElse(null);
170	            audit.record(ClaimStatus.OPEN.event() + " sheet=" + id + " by=" + user
171	                    + " person=" + (person == null ? "" : person.getName())
172	                    + " amount=" + claim.getAmount() + " date=" + claim.getDate()
173	                    + claim.getAuditNumber());
174	            Rollup after = Rollup.of(id, people, claims, rates, sheets, settings);
175	            for (String line : after.changesSince(before, id, user)) {
176	                audit.record(line);
177	            }
178	            before = after;
179	        }
180	        result.set(new BulkOpenResult(opened, selected.size() - opened));
181	    }
