242	 *  within a person), each by exactly the rules of {@link SettleClaim} and recorded as it would record
243	 *  it (its status log line, its CLAIM_SETTLED or CLAIM_PENDING line, a settled one's NOTIFY lines, then the rollup lines it moved).
244	 *  A claim gone to PENDING counts as settled. All or nothing: if any selected claim cannot be settled
245	 *  (its status does not allow it, the user opened it, its due-by is in a closed period, it is not on the
246	 *  sheet, or the sheet is archived) none is settled, every one counts as refused and nothing is written.
247	 *  Otherwise the bulk settle is the sheet's next batch, each claim keeps that batch number, and after the
248	 *  claims' own lines one BATCH_SETTLED line gives the batch, its count and the SETTLED ones' frozen dues added up. */
249	public class BulkSettleClaims {
250	    public void settle(@PathVariable("sheetId") String sheetId,
251	            @RequestParam(name = "by", required = false) String by,
252	            @RequestBody BulkSettleRequest request, ClaimRepository claims, PeriodRepository periods,
253	            PersonRepository people, RateRepository rates, SheetRepository sheets,
254	            SettingRepository settings, RoleRepository roles, ClaimLogRepository log, WatchRepository watches, Audit audit,
255	            Out<BulkSettleResult> result) {
256	        String id = sheetId.trim();
257	        String user = by == null ? "" : by;
258	        Set<Long> selected = new HashSet<>(request == null || request.claimIds() == null
259	                ? List.of() : request.claimIds());
260	        selected.remove(null);
261	
262	        // The selected claims of the sheet, in list order.
263	        List<Claim> all = claims.list(id);
264	        List<Claim> ordered = new ArrayList<>();
265	        for (Person p : people.list(id)) {
266	            for (Claim c : all) {
267	                if (c.getPersonId() == p.getId() && selected.contains(c.getId())) ordered.add(c);
268	            }
269	        }
270	
271	        // All or nothing: every selected claim must settle by the rules of settling one (going to PENDING
272	        // is not a refusal), or none is settled and every one counts as refused.
273	        boolean refused = sheets.isArchived(id) || ordered.size() != selected.size()
274	                || Role.VIEWER.equals(roles.roleOf(id, user));
275	        for (Claim claim : ordered) {
276	            if (refused) break;
277	            try {
278	                SettleClaim.settle(user, claim, people, rates, periods, roles, settings, sheets);
279	            } catch (ClaimStatusException | PeriodClosedException e) {
280	                refused = true;
281	            }
282	        }
283	        if (refused || ordered.isEmpty()) {
284	            result.set(new BulkSettleResult(0, selected.size()));
285	            return;
286	        }
287	
288	        int batch = sheets.nextSettleBatch(id);
289	        BigDecimal total = BigDecimal.ZERO.setScale(2);
290	        Rollup before = Rollup.of(id, people, claims, rates, sheets, settings);
291	        for (Claim claim : ordered) {
292	            claim.setSettleBatch(batch);
293	            claims.update(claim);
294	            log.record(claim, user);
295	            audit.record(RecordClaimStatus.line(ClaimStatus.valueOf(claim.getStatus()).event(), user, claim, people)
296	                    + (ClaimStatus.SETTLED.name().equals(claim.getStatus()) ? RecordClaimStatus.due(claim) : ""));
297	            if (ClaimStatus.SETTLED.name().equals(claim.getStatus())) {
298	                if (claim.getSettledDue() != null) total = total.add(new BigDecimal(claim.getSettledDue()));
299	                Notify.watchers(user, claim, people, watches, audit);
300	            }
301	            Rollup after = Rollup.of(id, people, claims, rates, sheets, settings);
302	            for (String line : after.changesSince(before, id, user)) {
303	                audit.record(line);
304	            }
305	            before = after;
306	        }
307	        audit.record("BATCH_SETTLED sheet=" + id + " by=" + user + " batch=" + batch
308	                + " count=" + ordered.size() + " total=" + total.toPlainString());
309	        result.set(new BulkSettleResult(ordered.size(), 0));
310	    }
311	}
