538	    /** The status after moving to {@code to}; refused when this status does not allow it. */
539	    public ClaimStatus moveTo(ClaimStatus to) throws ClaimStatusException {
540	        boolean allowed = switch (to) {
541	            case OPEN -> this == DRAFT || this == PENDING;
542	            case PENDING -> this == OPEN;
543	            case SETTLED -> this == OPEN || this == PENDING;
544	            case VOID -> this == DRAFT || this == OPEN || this == PENDING;
545	            case DRAFT -> false;
546	        };
547	        if (!allowed) {
548	            throw new ClaimStatusException("A " + this + " claim cannot become " + to);
549	        }
550	        return to;
