559	    public String event() {
560	        return switch (this) {
561	            case OPEN -> "CLAIM_OPENED";
562	            case PENDING -> "CLAIM_PENDING";
563	            case SETTLED -> "CLAIM_SETTLED";
564	            case VOID -> "CLAIM_VOIDED";
565	            case DRAFT -> "CLAIM_DRAFTED";
566	        };
567	    }
