        jdbc.update("INSERT INTO claim_comment (sheet_id, claim_id, by_user, on_date, text) VALUES (?, ?, ?, ?, ?)",
                claim.getSheetId(), claim.getId(), comment.by(), LocalDate.parse(comment.date()), comment.text());
