478	    public void take(@RequestParam(name = "asof", required = false) String asof, @Val Person person,
479	            PersonRepository people, ClaimRepository claims, RateRepository rates, SheetRepository sheets,
480	            SettingRepository settings) throws InvalidPersonException {
481	        String sheetId = person.getSheetId();
482	        LocalDate today = sheets.today(sheetId);
483	        LocalDate on = today;
