491	            own = claims.listOf(sheetId, person.getId());
492	            sheetRates = rates.list(sheetId);
493	            floor = settings.floor(sheetId);
494	            late = settings.late(sheetId, today);
495	            cap = settings.cap(sheetId);
496	        } else {
497	            try {
498	                on = LocalDate.parse(asof.trim());
499	            } catch (DateTimeParseException e) {
500	                throw new InvalidPersonException("The statement date must be a date");
501	            }
502	            if (on.isAfter(today)) {
503	                throw new InvalidPersonException("The statement date cannot be after the sheet's today");
504	            }
505	            if (people.addedAfter(sheetId, person.getId(), on)) {
506	                throw new InvalidPersonException("The person was not on the sheet on the statement date");
507	            }
508	            then = people.findAsOf(sheetId, person.getId(), on);
509	            own = claims.listOfAsOf(sheetId, person.getId(), on);
510	            sheetRates = rates.listAsOf(sheetId, on);
511	            floor = settings.datedAsOf(sheetId, SettingRepository.FLOOR, SettingRepository.DEFAULT_FLOOR, on);
512	            late = settings.lateAsOf(sheetId, on);
513	            cap = settings.capAsOf(sheetId, on);
514	            person.setStatedAsOf(on.toString());
515	        }
516	        // The figure each counting claim is bound to, by claim id.
517	        Map<Long, String> figures = new HashMap<>();
518	        BigDecimal total = BigDecimal.ZERO.setScale(2);
519	        boolean kept = false;
520	        for (Claim c : own) {
521	            if (!then.countsLive(c)) continue;
522	            String grade = then.gradeOn(c.getDate());
523	            Rate rate = RateRepository.inForce(sheetRates, grade, c.getDate());
524	            String live = rate == null ? null : Dues.of(c.getAmount(), rate.pct(), late.rounding(c.getRoundDate()));
525	            String shown = Dues.shown(c, live, floor.on(c.getDate()), late);
526	            kept |= c.getSettledDue() != null || c.isBound()
527	                    || (rate != null && (!grade.equals(then.getGrade())
528	                            || !LocalDate.parse(c.getDate()).isAfter(on)));
529	            if (shown != null) total = total.add(new BigDecimal(shown));
530	            // The rate figure under it is bound; its late charge and floor keep following the sheet's today.
531	            figures.put(c.getId(), c.due(live));
532	        }
533	        for (Claim c : claims.listOf(sheetId, person.getId())) {
534	            if (figures.containsKey(c.getId())) c.bind(true, figures.get(c.getId()));
535	            else c.bind(false, null);
536	            claims.updateBinding(c);
537	        }
538	        boolean na = RateRepository.inForce(sheetRates, then.getGrade(), on.toString()) == null && !kept;
539	        if (cap != null && total.compareTo(cap) > 0) total = cap.setScale(2);
