115	    private PeriodClosing() {
116	    }
117	    /** Close the open period now, as a close by hand does (no permission check): used by the
118	     *  sheet's today change to close the periods past their grace days. */
119	    public static Period closeNow(Period found, String user, PeriodRepository periods, ClaimRepository claims,
120	            ClaimLogRepository log, PersonRepository people, RateRepository rates, SettingRepository settings,
121	            SheetRepository sheets) {
122	        return fixNow(found, user, false, periods, claims, log, people, rates, settings, sheets);
123	    }
124	    /** Close or (soft) soft-close the period now, fixing its figures as they are now (no permission check). */
125	    public static Period fixNow(Period found, String user, boolean soft, PeriodRepository periods, ClaimRepository claims,
126	            ClaimLogRepository log, PersonRepository people, RateRepository rates, SettingRepository settings,
127	            SheetRepository sheets) {
128	        String id = found.sheetId();
129	        DatedSetting floor = settings.floor(id);
130	        Dues.Late late = settings.late(id, sheets.today(id));
131	        BigDecimal total = BigDecimal.ZERO.setScale(2);
132	        Map<Long, BigDecimal> personTotals = new LinkedHashMap<>();
133	        for (Person p : people.list(id)) personTotals.put(p.getId(), BigDecimal.ZERO.setScale(2));
134	        Map<Long, String> atEnd = log.statusesOn(id, LocalDate.parse(found.to()));
135	        for (Claim c : claims.list(id)) {
136	            if (!found.contains(c.getDueBy())) continue;
137	            String status = atEnd.containsKey(c.getId()) ? atEnd.get(c.getId()) : c.getStatus();
138	            if (status == null || !(ClaimStatus.isOpen(status) || ClaimStatus.SETTLED.name().equals(status))) continue;
139	            Person person = people.find(id, c.getPersonId());
140	            if (person != null && person.leftOutLive(c)) continue;
141	            Rate rate = person == null ? null
142	                    : rates.find(id, person.gradeOn(c.getDate()), LocalDate.parse(c.getDate()));
143	            String due = Dues.shown(c, rate == null ? null : Dues.of(c.getAmount(), rate.pct(), late.rounding(c.getRoundDate())), floor.on(c.getDate()), late);
144	            if (due != null) {
145	                total = total.add(new BigDecimal(due));
146	                if (person != null) personTotals.merge(person.getId(), new BigDecimal(due), BigDecimal::add);
147	            }
148	        }
149	        return periods.close(found, total, personTotals, user, soft);
