317	/**
318	 * A request about a sheet carrying {@code shown-asof=<yyyy-MM-dd>} comes from a screen showing the sheet as
319	 * of that date. A read (any GET, and loading the sheet) is answered from the sheet as it stood then
320	 * ({@link AsOfStore}), with the date as its today; every change is refused (403) before anything is
321	 * read or written, so nothing reaches the store or the audit file.
322	 */
323	@Component
324	@Order(Ordered.HIGHEST_PRECEDENCE + 100)
325	public class AsOfFilter extends OncePerRequestFilter {
326	    private static final Pattern SHEET = Pattern.compile("^/api/sheets/([^/]+)(/.*)?$");
327	    private final AsOfStore store;
328	    public AsOfFilter(AsOfStore store) {
329	        this.store = store;
330	    }
331	    @Override
332	    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain chain)
333	            throws ServletException, IOException {
334	        String asOf = request.getParameter("shown-asof");
335	        Matcher sheet = SHEET.matcher(request.getRequestURI().substring(request.getContextPath().length()));
336	        if (asOf == null || asOf.isBlank() || !sheet.matches()) {
337	            chain.doFilter(request, response);
338	            return;
339	        }
340	        boolean read = "GET".equals(request.getMethod())
341	                || ("POST".equals(request.getMethod()) && "/open".equals(sheet.group(2)));
342	        if (!read) {
343	            refuse(response, HttpStatus.FORBIDDEN, "The sheet is shown as of a date: nothing can be changed");
344	            return;
345	        }
346	        LocalDate date;
347	        try {
348	            date = LocalDate.parse(asOf.trim());
349	        } catch (DateTimeParseException e) {
350	            refuse(response, HttpStatus.BAD_REQUEST, "Not a date: " + asOf);
351	            return;
352	        }
353	        String schema = store.view(UriUtils.decode(sheet.group(1), StandardCharsets.UTF_8).trim(), date);
354	        AsOfView.enter(schema);
355	        try {
356	            chain.doFilter(request, response);
357	        } finally {
358	            AsOfView.leave();
359	            store.drop(schema);
360	        }
361	    }
362	    private static void refuse(HttpServletResponse response, HttpStatus status, String message) throws IOException {
363	        response.setStatus(status.value());
364	        response.setContentType("text/plain;charset=UTF-8");
365	        response.getWriter().write(message);
366	    }
367	}
