369	/**
370	 * What a sheet held as of a date. Each time the sheet's today changes, its rows are copied into a
371	 * schema of their own (SNAP_<id>, listed in sheet_snapshot). The sheet as of a date is what it held
372	 * at the last moment its today was on or before that date: the store as it is now while its today
373	 * still is, else the copy taken when its today last moved past that date, else nothing. A view
374	 * copies that into a schema the request reads (ASOF_<n>), with the date as the sheet's today, and
375	 * drops it after.
376	 *
377	 * Works on connections of its own, so a copy is never part of a request's transaction, and one copy
378	 * or drop at a time: H2 lets one session at a time change its schemas.
379	 */
380	@Component
381	public class AsOfStore {
382	    private static final String LIVE = "PUBLIC";
383	    /** Tables that are not the sheet's data. */
384	    private static final Set<String> SKIP = Set.of("flyway_schema_history", "SHEET_SNAPSHOT");
385	    private final DataSource dataSource;
386	    private final AtomicLong views = new AtomicLong();
387	    public AsOfStore(DataSource dataSource) {
388	        this.dataSource = dataSource;
389	    }
390	    /** Keep what the sheet holds now, before its today moves from {@code was} to {@code now}. */
391	    public synchronized void snapshot(String sheetId, LocalDate was, LocalDate now) {
392	        try (Connection c = dataSource.getConnection()) {
393	            c.setAutoCommit(true);
394	            long id;
395	            try (Statement s = c.createStatement();
396	                    ResultSet rs = s.executeQuery("SELECT NEXT VALUE FOR sheet_snapshot_seq")) {
397	                rs.next();
398	                id = rs.getLong(1);
399	            }
400	            copy(c, LIVE, "SNAP_" + id, sheetId);
401	            try (PreparedStatement ps = c.prepareStatement(
402	                    "INSERT INTO sheet_snapshot (id, sheet_id, today_was, today_now) VALUES (?, ?, ?, ?)")) {
403	                ps.setLong(1, id);
404	                ps.setString(2, sheetId);
405	                ps.setObject(3, was);
406	                ps.setObject(4, now);
407	                ps.executeUpdate();
408	            }
409	        } catch (SQLException e) {
410	            throw new IllegalStateException("Could not keep the sheet as of its today", e);
411	        }
412	    }
413	    /** A new schema holding the sheet as of the date, with the date as its today. */
414	    public synchronized String view(String sheetId, LocalDate asOf) {
415	        String schema = "ASOF_" + views.incrementAndGet();
416	        try (Connection c = dataSource.getConnection()) {
417	            c.setAutoCommit(true);
418	            String[] sheet = liveSheet(c, sheetId);
419	            String source;
420	            if (sheet != null && !LocalDate.parse(sheet[1]).isAfter(asOf)) {
421	                source = LIVE;
422	            } else {
423	                source = null;
424	                try (PreparedStatement ps = c.prepareStatement("SELECT id FROM sheet_snapshot "
425	                        + "WHERE sheet_id = ? AND today_was <= ? AND today_now > ? ORDER BY id DESC LIMIT 1")) {
426	                    ps.setString(1, sheetId);
427	                    ps.setObject(2, asOf);
428	                    ps.setObject(3, asOf);
429	                    try (ResultSet rs = ps.executeQuery()) {
430	                        if (rs.next()) source = "SNAP_" + rs.getLong(1);
431	                    }
432	                }
433	            }
434	            copy(c, source, schema, sheetId);
435	            if (source == null) {
436	                // Nothing on it yet: the sheet itself, as it was made.
437	                try (PreparedStatement ps = c.prepareStatement("INSERT INTO " + q(schema) + ".SHEET "
438	                        + "(ID, CREATED_BY, CREATED_AT, TODAY, LAST_CLAIM_NUMBER, ARCHIVED) "
439	                        + "VALUES (?, ?, CURRENT_TIMESTAMP, ?, 0, FALSE)")) {
440	                    ps.setString(1, sheetId);
441	                    ps.setString(2, sheet == null ? "" : sheet[0]);
442	                    ps.setObject(3, asOf);
443	                    ps.executeUpdate();
444	                }
