456	        }
457	    }
458	    /** Drop a view's schema once its request is done. */
459	    public synchronized void drop(String schema) {
460	        try (Connection c = dataSource.getConnection(); Statement s = c.createStatement()) {
461	            c.setAutoCommit(true);
462	            s.execute("DROP SCHEMA IF EXISTS " + q(schema) + " CASCADE");
