                List<Holiday> onSheet = holidays.getOrDefault(c.sheetId(), List.of());
                Set<LocalDate> then = new HashSet<>();
                Set<LocalDate> now = new HashSet<>();
                for (Holiday h : onSheet) {
                    now.add(h.day());
                    if (!h.addedAt().after(c.createdAt())) then.add(h.day());
                }
