189	function formatCents(cents: bigint): string {
190	  const abs = cents < 0n ? -cents : cents;
191	  const frac = (abs % 100n).toString().padStart(2, '0');
192	  return `${cents < 0n ? '-' : ''}${abs / 100n}.${frac}`;
193	}
194	
195	/** A due as shown: n/a when there is none. */
196	export const showDue = (due: string | null) => due ?? 'n/a';
197	
198	/** What a candidate rate for a grade on every date would change: how many open (OPEN or PENDING) claims
199	 *  of people on that grade on the claim's date would show a different due, and the sum of the differences
200	 *  (new minus current, two decimals). */
201	export type RatePreview = { count: number; diff: string };
202	
203	/** Preview a candidate rate for a grade; nothing is saved. Refused (rejects) when the percent is missing,
204	 *  negative or has more than two decimals. */
205	export function previewRate(sheetId: string, grade: string, pct: string): Promise<RatePreview> {
206	  return getJson<RatePreview>(`/api/sheets/${encodeURIComponent(sheetId)}/rate-preview`
207	    + `?grade=${encodeURIComponent(grade)}&pct=${encodeURIComponent(pct)}`);
208	}
209	import { getJson, postJson, putJson } from '../../api/http';
210	import { sheetKey } from '../sheet/api';
211	
212	/** A claim's status: DRAFT, opened to OPEN, settled to SETTLED (or, by a clerk above the clerk limit,
213	 *  to PENDING, which a steward approves to SETTLED or rejects back to OPEN); a DRAFT, OPEN or PENDING
214	 *  claim can be voided, and a SETTLED one by a steward within 7 days of its settlement. */
215	export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';
216	/** A change of a claim's status. */
217	export type ClaimAction = 'open' | 'settle' | 'void' | 'approve' | 'reject' | 'resettle';
218	
219	/** Whether a claim is open: OPEN, or PENDING a steward's approval. */
220	export const isOpen = (c: Pick<Claim, 'status'>) => c.status === 'OPEN' || c.status === 'PENDING';
221	
222	/** Whether a statement's figure binds a claim now: it was bound to one and is not PENDING (a PENDING
223	 *  claim shows and totals its live figure until it is rejected). */
224	export const isBound = (c: Claim) => c.stated && c.statedDue !== null && c.status !== 'PENDING';
225	
226	/** A claim: its amount as two-decimal text, its date (yyyy-MM-dd), its note, its status and its
227	 *  number on the sheet (given when opened: the sheet-wide 1, 2, ... or, under period numbering,
228	 *  <period>-<n> or X-<n>; null while a draft), and its settled due
229	 *  (fixed when settled; null otherwise, or when there was no rate then — its due stays live), and who
230	 *  opened it (null while a draft; that user cannot settle it), and whether its person's last statement
231	 *  bound it, with the figure it bound (null when it had none): a bound claim shows and totals that.
232	 *  A correction (a negative amount) has the number of the SETTLED claim it corrects (null otherwise).
233	 *  `roundDate` is the date its live figures round by: its own, or a correction's claim's it corrects.
234	 *  `dueBy` (yyyy-MM-dd) is fixed when it was added: its date then plus the terms of its person's
235	 *  grade in force on that date (the grade's own, else the sheet's). `log` is its status log, oldest
236	 *  first: `<STATUS> by <user> on <date> due=<due>`, the sheet's today and its due at each change.
237	 *  `deferredUntil` is the date it was last deferred until (null: never), and `deferred` whether it is
238	 *  deferred on the sheet's today (OPEN and deferred until a later date): a deferred claim counts in no
239	 *  total, is not overdue, cannot be settled and is left unbound by a statement. `proofs` is how many
240	 *  proofs it has: one whose due is above the proof threshold in force on its date cannot be settled or
241	 *  approved with none. */
242	export type Claim = {
243	  id: number; sheetId: string; personId: number; amount: string; date: string; note: string; status: ClaimStatus;
244	  number: string | null; settledDue: string | null; openedBy: string | null;
245	  stated: boolean; statedDue: string | null; corrects: string | null; roundDate: string; dueBy: string;
246	  log: string[]; deferredUntil: string | null; deferred: boolean; proofs: number;
247	  /** Its comments, oldest first: `<user> on <date>: <text>` (the sheet's today when written). */
248	  comments: string[];
249	  /** The number of the claim it was split from (null: not split off a claim). */
250	  splitFrom: string | null;
251	  /** The user whose open editor locks it for everyone else (null: unlocked). */
252	  lockedBy: string | null;
253	  /** Whether it was added while the period its due-by falls in was soft-closed. */
254	  lateEntry: boolean;
255	  /** The last sheet's today it was reminded on (null: never reminded). */
256	  reminded: string | null;
257	  /** Its external reference (null: none); used once per sheet, compared without regard to case. */
258	  ref: string | null;
259	  /** Its tags: trimmed, lower-cased, without repeats, sorted and comma separated (null: none). */
260	  tags: string | null;
261	  /** The reason it was voided with, from the sheet's void reasons (null: none). */
262	  voidReason: string | null;
263	  /** The number of the bulk settle batch that settled it (null: not settled by a bulk settle). */
264	  settleBatch: number | null;
265	};
266	/** `corrects`: the number of the SETTLED claim of the same person a correction (a negative amount) corrects.
267	 *  `ref`: its external reference (trimmed; blank: none), refused when already used on the sheet.
268	 *  `tags`: its tags, comma separated (each trimmed and lower-cased, repeats dropped; blank: none). */
269	export type ClaimInput = { amount: string; date: string; note: string; corrects: string; ref: string; tags: string };
270	
271	/** A claim's tags as shown: sorted, comma and space separated (blank: none). */
272	export const showTags = (tags: string | null) => (tags ?? '').split(',').filter((t) => t !== '').join(', ');
273	
274	/** A claim's tags as a list (empty: none). */
275	export const tagsOf = (c: Pick<Claim, 'tags'>) => (c.tags ?? '').split(',').filter((t) => t !== '');
276	
277	/** Whether a claim is a correction: its amount is negative. */
278	export const isCorrection = (c: Pick<Claim, 'amount'>) => c.amount.trim().startsWith('-') && Number(c.amount) !== 0;
279	
280	const sheetBase = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}`;
281	
282	export const claimsKey = (sheetId: string) => [...sheetKey(sheetId), 'claims'] as const;
283	
284	/** Under the claims' key, so whatever refreshes the claims refreshes the tags too. */
285	export const tagsKey = (sheetId: string) => [...claimsKey(sheetId), 'tags'] as const;
286	
287	/** Every tag ever used on the sheet's claims, sorted. */
288	export function listTags(sheetId: string): Promise<string[]> {
289	  return getJson<string[]>(`${sheetBase(sheetId)}/tags`);
290	}
291	
292	/** Every claim on the sheet, newest first. */
293	export function listClaims(sheetId: string): Promise<Claim[]> {
294	  return getJson<Claim[]>(`${sheetBase(sheetId)}/claims`);
295	}
296	
297	/** Add a claim to a person; refused (rejects) when the amount is missing or has more than two
298	 *  decimals, the date is not a date, or it is a correction (negative) that does not name by number a
299	 *  SETTLED claim of the person, or its reference is already used on the sheet (in any case). A blank date takes the sheet's entry date when set, else its today. */
300	export function addClaim(sheetId: string, by: string, personId: number, input: ClaimInput): Promise<Claim> {
301	  return postJson<Claim>(`${sheetBase(sheetId)}/people/${personId}/claims?by=${encodeURIComponent(by)}`, input);
302	}
303	
304	/** Edit a claim; refused (rejects) like an add. */
305	export function updateClaim(sheetId: string, by: string, id: number, input: ClaimInput): Promise<Claim> {
306	  return putJson<Claim>(`${sheetBase(sheetId)}/claims/${id}?by=${encodeURIComponent(by)}`, input);
307	}
308	
309	/** Open a claim's editor, locking it for other users until it is saved or cancelled or the sheet's
310	 *  today changes (and releasing any other claim of its person the user held); refused (rejects) with
311	 *  409 when it is not a DRAFT, 423 when due by a day in a closed period, 412 while another user holds it. */
312	export function lockClaim(sheetId: string, by: string, id: number): Promise<Claim> {
313	  return postJson<Claim>(`${sheetBase(sheetId)}/claims/${id}/lock?by=${encodeURIComponent(by)}`, {});
314	}
315	
316	/** Cancel a claim's editor, releasing its lock when the user holds it. */
317	export function unlockClaim(sheetId: string, by: string, id: number): Promise<Claim> {
318	  return postJson<Claim>(`${sheetBase(sheetId)}/claims/${id}/unlock?by=${encodeURIComponent(by)}`, {});
319	}
320	
321	/** Change a claim's status; refused (rejects) when its status does not allow the change, when the
322	 *  user settling or approving it is the one who opened it, when a non-steward approves or rejects it,
323	 *  or when a rejection has no `reason`, or a void none from the sheet's void reasons while it has any. A steward's `resettle` freezes a SETTLED claim again at the
324	 *  figure it would have today as an open claim bound by no statement. */
325	export function moveClaim(sheetId: string, by: string, id: number, action: ClaimAction, reason = ''): Promise<Claim> {
326	  const extra = action === 'reject' || action === 'void' ? `&reason=${encodeURIComponent(reason)}` : '';
327	  return postJson<Claim>(`${sheetBase(sheetId)}/claims/${id}/${action}?by=${encodeURIComponent(by)}${extra}`, {});
328	}
329	
330	/** Defer an OPEN claim until a date after the sheet's today; refused (rejects) when it is not OPEN,
331	 *  the date is not after today, or it is due by a day in a closed period. */
332	export function deferClaim(sheetId: string, by: string, id: number, until: string): Promise<Claim> {
333	  return postJson<Claim>(`${sheetBase(sheetId)}/claims/${id}/defer?by=${encodeURIComponent(by)}&until=${encodeURIComponent(until)}`, {});
334	}
335	
336	/** Remind an OPEN or PENDING claim on the sheet's today; refused (rejects) with 409 for any other
337	 *  status, or when it was already reminded on the sheet's today. */
338	export function remindClaim(sheetId: string, by: string, id: number): Promise<Claim> {
339	  return postJson<Claim>(`${sheetBase(sheetId)}/claims/${id}/remind?by=${encodeURIComponent(by)}`, {});
340	}
341	
342	/** A steward re-dates an OPEN or PENDING claim to `date`: its due-by and any bound figure stay, and
343	 *  so do its period (the one its due-by falls in) and its number. Refused (rejects) for anyone else, any other status, a date after its person's
344	 *  retirement, or a claim due by a day in a closed period. */
345	export function redateClaim(sheetId: string, by: string, id: number, date: string): Promise<Claim> {
346	  return postJson<Claim>(`${sheetBase(sheetId)}/claims/${id}/redate?by=${encodeURIComponent(by)}&date=${encodeURIComponent(date)}`, {});
347	}
348	
349	/** Split an OPEN claim: it keeps the rest of its amount and loses any figure a statement bound it to;
350	 *  a new OPEN claim of `amount` (more than 0.00, less than the claim's), opened by the user, is split
351	 *  from its number. Refused (rejects) for a PENDING, deferred or settled claim, one due by a day in a closed
352	 *  period, an amount out of range, or a role that may not open a claim. */
353	export function splitClaim(sheetId: string, by: string, id: number, amount: string): Promise<Claim> {
354	  return postJson<Claim>(`${sheetBase(sheetId)}/claims/${id}/split?by=${encodeURIComponent(by)}&amount=${encodeURIComponent(amount)}`, {});
355	}
356	
357	/** Raise a claim's proofs count by one; refused (rejects) for a SETTLED or VOID claim, or one dated
358	 *  in a closed period. */
359	export function addProof(sheetId: string, by: string, id: number): Promise<Claim> {
360	  return postJson<Claim>(`${sheetBase(sheetId)}/claims/${id}/proofs?by=${encodeURIComponent(by)}`, {});
361	}
362	
363	/** Comment a claim, by the user on the sheet's today; refused (rejects) for an empty comment. */
364	export function commentClaim(sheetId: string, by: string, id: number, text: string): Promise<Claim> {
365	  return postJson<Claim>(`${sheetBase(sheetId)}/claims/${id}/comments?by=${encodeURIComponent(by)}&text=${encodeURIComponent(text)}`, {});
366	}
367	
368	/** A steward moves a DRAFT, OPEN or PENDING claim to another person (`toPersonId`): it keeps its
369	 *  number and date, loses any figure a statement bound it to, and is listed as that person's newest
370	 *  claim. Refused (rejects) for anyone else, for a SETTLED or VOID claim, or one due by a day in a closed period. */
371	export function reassignClaim(sheetId: string, by: string, id: number, toPersonId: number): Promise<Claim> {
372	  return postJson<Claim>(`${sheetBase(sheetId)}/claims/${id}/reassign?by=${encodeURIComponent(by)}&to=${toPersonId}`, {});
373	}
374	
375	/** Whether a claim counts toward claimed, due-total and every total: only OPEN, PENDING and SETTLED do. */
376	export const counts = (c: Claim) => isOpen(c) || c.status === 'SETTLED';
377	
378	/** The claims that count in live totals: all but the deferred claims and the open claims that no statement bound,
379	 *  dated within one of their person's holds (`to` null: open-ended) or of a person whose retirement date the sheet's
380	 *  today has reached (`retiredReached`) (SETTLED and bound claims still count). */
381	export function liveClaims(claims: Claim[],
382	  people: Array<{ id: number; holds: Array<{ from: string; to: string | null }>; retiredReached?: boolean }> | undefined): Claim[] {
383	  const byId = new Map((people ?? []).map((p) => [p.id, p]));
384	  const held = (c: Claim) => {
385	    const p = byId.get(c.personId);
386	    return !!p && (!!p.retiredReached || p.holds.some((h) => h.from <= c.date && (h.to === null || c.date <= h.to)));
387	  };
388	  return claims.filter((c) => !c.deferred && !(isOpen(c) && !c.stated && held(c)));
389	}
390	
391	/** Whether a person is active: one of their claims that count (`live`, see `liveClaims`) is open (OPEN or
392	 *  PENDING) and dated within the 30 days up to and including the sheet's `today`. */
393	export function isActive(live: Claim[], today: string): boolean {
394	  if (today === '') return false;
395	  const since = new Date(`${today}T00:00:00Z`);
396	  since.setUTCDate(since.getUTCDate() - 29);
397	  const from = since.toISOString().slice(0, 10);
398	  return live.some((c) => isOpen(c) && from <= c.date && c.date <= today);
399	}
400	
401	/** A person's backing: the frozen settled figures of their patrons' SETTLED claims dated within the 90 days up to
402	 *  and including the sheet's `today`, added up (0.00 with none). */
403	export function backing(claims: Claim[], patronIds: number[], today: string): string {
404	  if (today === '') return '0.00';
405	  const since = new Date(`${today}T00:00:00Z`);
406	  since.setUTCDate(since.getUTCDate() - 89);
407	  const from = since.toISOString().slice(0, 10);
408	  const patrons = new Set(patronIds);
409	  const cents = claims
410	    .filter((c) => patrons.has(c.personId) && c.status === 'SETTLED' && c.settledDue !== null && from <= c.date && c.date <= today)
411	    .reduce((t, c) => t + Math.round(Number(c.settledDue) * 100), 0);
412	  return (cents / 100).toFixed(2);
413	}
414	
415	/** Sum the amounts of the claims that count (see `counts`) exactly (in cents), shown with two decimals. */
416	export function sumAmounts(claims: Claim[]): string {
417	  const cents = claims.filter(counts).reduce((t, c) => t + Math.round(Number(c.amount) * 100), 0);
418	  return (cents / 100).toFixed(2);
419	}
420	
421	/** A claim's due-by (yyyy-MM-dd), fixed when it was added. */
422	export const dueBy = (c: Claim): string => c.dueBy;
423	
424	/** Whether a claim is overdue: it is open (OPEN or PENDING), not deferred, and the date its lateness counts
425	 *  from (`lateFrom`: its due-by plus its grace days; by default its due-by) is before the sheet's `today`. */
426	export const isOverdue = (c: Claim, today: string, lateFrom: string = dueBy(c)) =>
427	  isOpen(c) && !c.deferred && today !== '' && lateFrom < today;
428	
429	/** How many of the selected claims a bulk open opened, and how many it refused (left as they were). */
430	export type BulkOpenResult = { opened: number; refused: number };
431	
432	/** Open the selected claims together, numbered in list order (people in added order, newest claim
433	 *  first within a person); each that cannot be opened is left as it is and counted as refused. */
434	export function bulkOpenClaims(sheetId: string, by: string, claimIds: number[]): Promise<BulkOpenResult> {
435	  return postJson<BulkOpenResult>(`${sheetBase(sheetId)}/bulk-open?by=${encodeURIComponent(by)}`, { claimIds });
436	}
437	
438	/** How many of the selected claims a bulk settle settled (one gone to PENDING counts), and how many
439	 *  it refused (left as they were). */
440	export type BulkSettleResult = { settled: number; refused: number };
441	
442	/** Settle the selected claims together in list order (people in added order, newest claim first
443	 *  within a person), each by the rules of settling one; each that cannot be settled is left as it is
444	 *  and counted as refused. */
445	export function bulkSettleClaims(sheetId: string, by: string, claimIds: number[]): Promise<BulkSettleResult> {
446	  return postJson<BulkSettleResult>(`${sheetBase(sheetId)}/bulk-settle?by=${encodeURIComponent(by)}`, { claimIds });
447	}
448	
449	/** Under the claims' key, so whatever refreshes the claims refreshes it too. */
450	export const settleBatchKey = (sheetId: string) => [...claimsKey(sheetId), 'settle-batch'] as const;
451	
452	/** The number of the sheet's last bulk settle batch (null: there has been none). */
453	export function lastSettleBatch(sheetId: string): Promise<{ last: number | null }> {
454	  return getJson<{ last: number | null }>(`${sheetBase(sheetId)}/settle-batch`);
455	}
456	
457	/** How many claims a paste added. */
458	export type PasteResult = { added: number };
459	
460	/** Add a DRAFT claim per line of name,amount,date,note (the note may hold commas, and may end in
461	 *  ` #<reference>`, the claim's reference, refused when used on the sheet or by another line; a blank date takes
462	 *  the sheet's entry date when set, else its today; the note may be absent), in order, to the named person; refused (rejects),
463	 *  adding nothing, when any line would be refused by the claim form or names no one on the sheet. */
464	export function pasteClaims(sheetId: string, by: string, text: string): Promise<PasteResult> {
465	  return postJson<PasteResult>(`${sheetBase(sheetId)}/paste-claims?by=${encodeURIComponent(by)}`, { text });
466	}
467	
468	/** A reason on the sheet's list of void reasons (trimmed): while the list is not empty, a claim is voided
469	 *  with one of them. */
470	export type VoidReason = { sheetId: string; reason: string; by: string };
471	
472	export const voidReasonsKey = (sheetId: string) => [...sheetKey(sheetId), 'void-reasons'] as const;
473	
474	/** The sheet's void reasons, in the order they were added. */
475	export function listVoidReasons(sheetId: string): Promise<VoidReason[]> {
476	  return getJson<VoidReason[]>(`${sheetBase(sheetId)}/void-reasons`);
477	}
478	
479	/** Add a void reason; refused (rejects) for a blank one or one already on the list. */
480	export function addVoidReason(sheetId: string, by: string, reason: string): Promise<VoidReason> {
481	  return postJson<VoidReason>(`${sheetBase(sheetId)}/void-reasons?by=${encodeURIComponent(by)}`, { reason });
482	}
483	
484	/** How many of the selected claims a bulk reassign moved, and how many it refused (left as they were). */
485	export type BulkReassignResult = { reassigned: number; refused: number };
486	
487	/** Move the selected claims to one person (`toPersonId`) together in list order (people in added order,
488	 *  newest claim first within a person), each by the rules of reassigning one; each that cannot be moved
489	 *  is left as it is and counted as refused. */
490	export function bulkReassignClaims(sheetId: string, by: string, claimIds: number[], toPersonId: number): Promise<BulkReassignResult> {
491	  return postJson<BulkReassignResult>(`${sheetBase(sheetId)}/bulk-reassign?by=${encodeURIComponent(by)}`, { claimIds, to: toPersonId });
492	}
