/** The sheet's claimed-total: everyone's OPEN and SETTLED claims added up (but the OPEN claims dated
 *  within a hold of their person, unless a statement bound them). */
export function ClaimedTotal({ sheetId }: { sheetId: string; user: string }) {
  const people = useQuery({ queryKey: peopleKey(sheetId), queryFn: () => listPeople(sheetId) });
  const claims = useQuery({ queryKey: claimsKey(sheetId), queryFn: () => listClaims(sheetId) });
  return (
    <p>
      Claimed total <span data-testid="rollup-claimed-total">{sumAmounts(liveClaims(claims.data ?? [], people.data))}</span>
    </p>
  );
}

/** For every tag ever used on the sheet, its due-total: the due figures of the claims that count (the
 *  live ones, OPEN, PENDING or SETTLED) carrying it, added up (n/a ones skipped); a claim with two tags
 *  counts in both. */
export function TagTotals({ sheetId, user }: { sheetId: string; user: string }) {
  const people = useQuery({ queryKey: peopleKey(sheetId), queryFn: () => listPeople(sheetId) });
  const claims = useQuery({ queryKey: claimsKey(sheetId), queryFn: () => listClaims(sheetId) });
  const used = useQuery({ queryKey: tagsKey(sheetId), queryFn: () => listTags(sheetId) });
  const rates = useQuery({ queryKey: ratesKey(sheetId), queryFn: () => listRates(sheetId) });
  const floor = useFloor(sheetId);
  const today = useSheetToday(sheetId, user);
  const charges = useLate(sheetId, today);
  const byId = new Map((people.data ?? []).map((p) => [p.id, p]));
  const live = liveClaims(claims.data ?? [], people.data).filter((c) => counts(c) && byId.has(c.personId));
  const tags = [...new Set([...(used.data ?? []), ...(claims.data ?? []).flatMap(tagsOf)])].sort();
  if (tags.length === 0) return null;
  const dueOf = (tag: string) => sumDues(live.filter((c) => tagsOf(c).includes(tag)).map((c) => {
    const p = byId.get(c.personId)!;
    return claimDue(c, rates.data, (d) => gradeOn(p, d), floor, charges);
  }));
  return (
    <p>
      Due by tag{' '}
      {tags.map((t) => (
        <span key={t}>
          {t} <span data-testid={`tag-${t}-due-total`}>{dueOf(t)}</span>{' '}
        </span>
      ))}
    </p>
  );
}

/** Per calendar month (yyyy-mm) any claim on the sheet is dated in, the due of the claims dated in it
 *  that count (live ones only, see `liveClaims`), n/a ones skipped; earliest month first. */
export function MonthTotals({ sheetId, user }: { sheetId: string; user: string }) {
  const people = useQuery({ queryKey: peopleKey(sheetId), queryFn: () => listPeople(sheetId) });
  const claims = useQuery({ queryKey: claimsKey(sheetId), queryFn: () => listClaims(sheetId) });
  const rates = useQuery({ queryKey: ratesKey(sheetId), queryFn: () => listRates(sheetId) });
  const floor = useFloor(sheetId);
  const today = useSheetToday(sheetId, user);
  const charges = useLate(sheetId, today);
  const all = claims.data ?? [];
  const byId = new Map((people.data ?? []).map((p) => [p.id, p]));
  const live = liveClaims(all, people.data).filter(counts);
  const months = [...new Set(all.map((c) => c.date.slice(0, 7)))].sort();
  const dueIn = (m: string) => sumDues(live.filter((c) => c.date.slice(0, 7) === m).map((c) => {
    const p = byId.get(c.personId);
    return p ? claimDue(c, rates.data, (d) => gradeOn(p, d), floor, charges) : null;
  }));
  return (
    <section>
      <h3>Monthly due</h3>
      <ul>
        {months.map((m) => (
          <li key={m}>{m} <span data-testid={`month-${m}-due-total`}>{dueIn(m)}</span></li>
        ))}
      </ul>
    </section>
  );
}

/** The sheet's overdue claims: how many of the claims that count are OPEN past their due-by, and
 *  their due (with its late charge) added up per person, the sheet's total leaving out the single
 *  highest and lowest person's when there are three or more people. */
export function useOverdue(sheetId: string, user: string): ReturnType<typeof overdue> {
  const people = useQuery({ queryKey: peopleKey(sheetId), queryFn: () => listPeople(sheetId) });
  const claims = useQuery({ queryKey: claimsKey(sheetId), queryFn: () => listClaims(sheetId) });
  const rates = useQuery({ queryKey: ratesKey(sheetId), queryFn: () => listRates(sheetId) });
  const floor = useFloor(sheetId);
  const today = useSheetToday(sheetId, user);
  const charges = useLate(sheetId, today);
  const byId = new Map<number, Person>((people.data ?? []).map((p) => [p.id, p]));
  const live = liveClaims(claims.data ?? [], people.data).filter((c) => byId.has(c.personId));
  const dueOf = (c: Parameters<typeof claimDue>[0]) => claimDue(c, rates.data, (d) => gradeOn(byId.get(c.personId)!, d), floor, charges);
  const perPerson = (people.data ?? []).map((p) => overdue(live.filter((c) => c.personId === p.id), charges, dueOf).total);
  return { count: overdue(live, charges, dueOf).count, total: trimmedSum(perPerson) };
}

export function Overdue({ sheetId, user }: { sheetId: string; user: string }) {
  const late = useOverdue(sheetId, user);
  return (
    <p>
      Overdue <span data-testid="rollup-overdue-count">{late.count}</span>{' '}
      totalling <span data-testid="rollup-overdue-total">{late.total}</span>
    </p>
  );
}
/** One CSV value: wrapped in double quotes (any quote inside doubled) when it holds a comma, a
 *  quote or a line break. */
const csvValue = (v: string) => (/[",\r\n]/.test(v) ? `"${v.replace(/"/g, '""')}"` : v);

/** The "export people" button: downloads `rows` as a CSV file under a header line, each line
 *  ending with a line feed. */
export function ExportPeople({ rows }: { rows: () => string[][] }) {
  const download = () => {
    const lines = [['name', 'grade', 'retired-from', 'due-total'], ...rows()];
    const csv = lines.map((l) => l.map(csvValue).join(',') + '\n').join('');
    const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv' }));
    const a = document.createElement('a');
    a.href = url;
    a.download = 'people.csv';
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 0);
  };
  return (
    <button type="button" data-testid="export-people" onClick={download}>
      Export people
    </button>
  );
}

